let best = numbers[0];
for (const x of numbers) { if (x > best) best = x; }
return best;

solution:
function maxOf(numbers) {
  let best = numbers[0];
  for (const x of numbers) {
    if (x > best) {
      best = x;
    }
  }
  return best;
}

